 "content": "from collections import deque, Counter


def transform(grid):
    """Fill each rectangular frame with a checkerboard of the matching marker color."""
    h, w = len(grid), len(grid[0])
    a = [row[:] for row in grid]
    seen = set()
    frame_cells = set()
    frames = []

    # A frame is a single connected component forming a complete rectangular outline.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            ys = [p[0] for p in comp]
            xs = [p[1] for p in comp]
            top, bottom, left, right = min(ys), max(ys), min(xs), max(xs)
            if bottom - top < 2 or right - left < 2:
                continue
            border = {(top, x) for x in range(left, right + 1)} | {(bottom, x) for x in range(left, right + 1)}
            border |= {(y, left) for y in range(top, bottom + 1)} | {(y, right) for y in range(top, bottom + 1)}
            if set(comp) == border:
                frames.append((top, bottom, left, right, color))
                frame_cells |= border

    # Dots outside the frames are color counts; each count identifies a frame's
    # checkerboard capacity. Remove the dots and distribute their color inside.
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r, c) not in frame_cells)
    by_capacity = {n: color for color, n in counts.items()}
    for top, bottom, left, right, _ in frames:
        interior = [(r, c) for r in range(top + 1, bottom)
                    for c in range(left + 1, right)
                    if (r + c - (top + 1) - (left + 1)) % 2 == 0]
        fill = by_capacity.get(len(interior))
        if fill is not None:
            for r, c in interior:
                a[r][c] = fill
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in frame_cells:
                a[r][c] = 0
    return a
